using System.ComponentModel;
using Microsoft.SemanticKernel;

public class OrderManagementPlugin
{
    private readonly IOrderRepository _repository;

    public OrderManagementPlugin(IOrderRepository repository)
    {
        _repository = repository;
    }

    [KernelFunction("get_order_status")]
    [Description("Retrieves the current fulfillment and delivery status for a given customer order ID.")]
    public async Task<OrderStatusDto> GetOrderStatusAsync(
        [Description("The unique order number (e.g. ORD-9821)")] string orderId,
        CancellationToken ct = default)
    {
        var order = await _repository.FindByIdAsync(orderId, ct);
        if (order == null)
            throw new KeyNotFoundException($"Order {orderId} not found.");

        return new OrderStatusDto(order.Id, order.Status, order.EstimatedDeliveryDate);
    }

    [KernelFunction("cancel_order")]
    [Description("Cancels an active order if it has not yet entered shipping status.")]
    public async Task<string> CancelOrderAsync(
        [Description("The order number to cancel")] string orderId,
        [Description("Reason provided by the customer for cancellation")] string reason,
        CancellationToken ct = default)
    {
        var success = await _repository.TryCancelAsync(orderId, reason, ct);
        return success ? $"Order {orderId} was successfully cancelled." : $"Order {orderId} cannot be cancelled as it is already in transit.";
    }
}

public record OrderStatusDto(string OrderId, string Status, DateTime? DeliveryDate);

using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.ChatCompletion;
using Microsoft.SemanticKernel.Connectors.OpenAI;

// 1. Build kernel and import plugin
var kernel = builder.Build();
kernel.Plugins.AddFromType<OrderManagementPlugin>("OrderManagement");

var chatService = kernel.GetRequiredService<IChatCompletionService>();
var history = new ChatHistory();
history.AddUserMessage("Where is my order ORD-9821, and can I cancel it if it hasn't shipped?");

// 2. Enable automatic function calling loop
var executionSettings = new OpenAIPromptExecutionSettings
{
    ToolCallBehavior = ToolCallBehavior.AutoInvokeKernelFunctions,
    Temperature = 0.2
};

// 3. The kernel automatically calls GetOrderStatusAsync and synthesizes the grounded answer
var response = await chatService.GetChatMessageContentAsync(
    history,
    executionSettings,
    kernel);

Console.WriteLine(response.Content);
